$('.menu-toggle')?.addEventListener('click',()=>{let open=$('#main-nav').classList.toggle('open');$('.menu-toggle').setAttribute('aria-expanded',String(open));});
$('#main-nav')?.addEventListener('click',e=>{if(e.target.closest('a')){$('#main-nav').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false');}});
function updateProgress(){const h=document.documentElement.scrollHeight-innerHeight;$('.progress').style.width=(h>0?Math.min(100,scrollY/h*100):0)+'%';}addEventListener('scroll',updateProgress,{passive:true});updateProgress();
async function copy(text){try{if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(text);toast('已复制到剪贴板。');return;}throw new Error();}catch{const t=document.createElement('textarea');t.value=text;t.style.position='fixed';t.style.top='-1000px';document.body.append(t);t.select();const ok=document.execCommand('copy');t.remove();toast(ok?'已复制到剪贴板。':'无法自动复制，请手动选择文本复制。');}}
$$('[data-copy]').forEach(el=>el.addEventListener('click',()=>copy(el.dataset.copy)));
$$('[data-copy-url]').forEach(el=>el.addEventListener('click',()=>copy(location.href)));
$$('[data-print]').forEach(el=>el.addEventListener('click',()=>window.print()));
function refreshSave(){const saved=read(keys.saved);$$('[data-save]').forEach(el=>{const yes=saved.some(x=>x?.path===el.dataset.save);el.textContent=yes?'已收藏 · 点击取消':el.dataset.save.startsWith('brands/')?'收藏品牌':el.dataset.save.startsWith('topics/')?'收藏专题':'收藏文章';el.setAttribute('aria-pressed',String(yes));});}
$$('[data-save]').forEach(el=>el.addEventListener('click',()=>{let saved=read(keys.saved);if(saved.some(x=>x?.path===el.dataset.save)){saved=saved.filter(x=>x?.path!==el.dataset.save);const persisted=write(keys.saved,saved);toast(persisted?'已取消收藏。':'已取消收藏，本次仅在当前页面生效。');}else{const persisted=write(keys.saved,[{path:el.dataset.save,title:el.dataset.title,date:new Date().toISOString()},...saved].slice(0,200));toast(persisted?'已收藏到当前浏览器。':'已收藏，本次仅在当前页面保留。');}refreshSave();}));refreshSave();
const currentPath=document.body.dataset.page.replace(/index\.html$/,'');
if(/^(blog|brands|topics)\/.+\/$/.test(currentPath)){const title=$('h1')?.textContent?.trim()||document.title;write(keys.history,[{path:currentPath,title,date:new Date().toISOString()},...read(keys.history).filter(x=>x?.path!==currentPath)].slice(0,30));}
function collectionCard(x){if(!x||!/^(blog|brands|topics)\/[a-z0-9-]+\/$/.test(x.path))return '';return `<article class="card"><div class="eyebrow">${x.path.startsWith('brands/')?'品牌档案':x.path.startsWith('topics/')?'专题研究':'选购文章'}</div><h3><a href="${E(href(x.path))}">${E(x.title)}</a></h3><div class="card-bottom"><span>当前浏览器本地记录</span></div></article>`;}
function renderLibrary(){if(!$('#library-saved'))return;$('#library-saved').innerHTML=read(keys.saved).map(collectionCard).join('')||'<div class="empty"><h3>还没有收藏</h3><p>阅读品牌、文章或专题时，点击收藏即可保存在这里。</p></div>';$('#library-history').innerHTML=read(keys.history).map(collectionCard).join('')||'<div class="empty"><h3>还没有最近阅读</h3><p>阅读品牌、文章或专题后，会在当前浏览器留下记录。</p></div>';}
$$('[data-library-clear]').forEach(el=>el.addEventListener('click',()=>{write(keys.saved,[]);renderLibrary();toast('当前浏览器的收藏已清空。');}));$$('[data-history-clear]').forEach(el=>el.addEventListener('click',()=>{write(keys.history,[]);renderLibrary();toast('当前浏览器的最近浏览已清除。');}));renderLibrary();
$('#brand-query')?.addEventListener('input',()=>{const q=$('#brand-query').value.trim().toLowerCase();let count=0;$$('[data-brand-row]').forEach(el=>{el.hidden=!el.dataset.search.toLowerCase().includes(q);if(!el.hidden)count++;});$('#brand-count').textContent=`${count}个匹配品牌 · 保持收录顺序`;});
let articlePage=1;const articlePageSize=12;
function filterArticles(){if(!$('#blog-filter'))return;const q=$('#article-query').value.trim().toLowerCase(),topic=$('#article-topic').value,kind=$('#article-kind').value;const matches=$$('[data-article-card]').filter(el=>el.dataset.search.toLowerCase().includes(q)&&(!topic||el.dataset.topics.split(' ').includes(topic))&&(!kind||el.dataset.kind===kind));const total=Math.ceil(matches.length/articlePageSize);articlePage=Math.max(1,Math.min(articlePage,total||1));$$('[data-article-card]').forEach(el=>el.hidden=true);matches.slice((articlePage-1)*articlePageSize,articlePage*articlePageSize).forEach(el=>el.hidden=false);$('#article-count').textContent=matches.length?`找到${matches.length}篇文章 · 显示${(articlePage-1)*articlePageSize+1}–${Math.min(matches.length,articlePage*articlePageSize)}篇`:'没有匹配的文章';$('.article-pagination').hidden=total<=1;$('#article-page').textContent=`${articlePage} / ${total||1}`;$('#previous-articles').disabled=articlePage<=1;$('#next-articles').disabled=articlePage>=total;$('#article-empty').hidden=matches.length>0;}
$('#blog-filter')?.addEventListener('input',()=>{articlePage=1;filterArticles();});$('#blog-filter')?.addEventListener('submit',e=>{e.preventDefault();articlePage=1;filterArticles();});for(const [id,delta] of [['previous-articles',-1],['next-articles',1]])$('#'+id)?.addEventListener('click',()=>{articlePage+=delta;filterArticles();$('#article-count').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});});filterArticles();
let selected=read(keys.compare).filter(x=>typeof x==='string'&&/^[a-z0-9-]+$/.test(x)).slice(0,4);
function refreshCompare(){write(keys.compare,selected);$$('[data-compare]').forEach(el=>{el.checked=selected.includes(el.dataset.compare);});$$('[data-compare-toggle]').forEach(el=>{const yes=selected.includes(el.dataset.compareToggle);el.textContent=yes?'已加入 · 点击移除':'加入对比';el.setAttribute('aria-pressed',String(yes));});const tray=$('.compare-tray');tray.hidden=!selected.length;$('#compare-count').textContent=`已选择${selected.length}家，最多4家${selected.length<2?'；再选择1家即可并排对比':''}`;const a=$('[data-compare-open]');a.href=href('compare/?brands='+encodeURIComponent(selected.join(',')));a.setAttribute('aria-disabled',String(selected.length<2));if($('#compare-selection'))renderComparison();}
function toggleCompare(id,checked=null){if(selected.includes(id)){if(checked!==true)selected=selected.filter(x=>x!==id);}else if(checked!==false){if(selected.length>=4){toast('最多对比4个品牌，请先移除一项。');refreshCompare();return;}selected.push(id);}refreshCompare();}
$$('[data-compare]').forEach(el=>el.addEventListener('change',()=>toggleCompare(el.dataset.compare,el.checked)));$$('[data-compare-toggle]').forEach(el=>el.addEventListener('click',()=>toggleCompare(el.dataset.compareToggle)));$('[data-compare-clear]')?.addEventListener('click',()=>{selected=[];refreshCompare();});$('[data-compare-open]')?.addEventListener('click',e=>{if(selected.length<2){e.preventDefault();toast('请至少选择2个品牌。');}});
const fromQuery=new URLSearchParams(location.search).get('brands');if($('#compare-selection')&&fromQuery){selected=[...new Set(fromQuery.split(',').filter(x=>/^[a-z0-9-]+$/.test(x)))].slice(0,4);}refreshCompare();
async function renderComparison(){const mount=$('#compare-selection');if(!mount)return;try{const data=await getData();const bs=data.brands.filter(b=>selected.includes(b.id));if(bs.length<2){mount.innerHTML='<div class="note">在下表选择2–4家品牌，生成并排比较。表格仍按原有品牌顺序展示。</div>';return;}const rows=[['月付参考起价',b=>{const m=monthlyReferencePlan(b);return b.planAttribution==='disputed'||b.id==='kosing'||!m?'暂不输出起价':m?`¥${money(m.price)} / 月；${quotaLabel(m)}`:'容量待核实';}],['方案摘要',b=>b.profile.deck],['核对事项',b=>b.profile.tradeoff],['线路资料',b=>b.line],['付款方式',b=>[...new Set(b.plans.map(p=>p.cycle))].join('、')||'待当前商城确认'],['优惠码',b=>b.coupon?b.coupon+(b.couponTerms?' · '+b.couponTerms.summary:' · 适用条件见品牌页'):'未提供'],['档案',b=>`<a href="${href('brands/'+b.id+'/')}">阅读完整档案</a>`]];mount.innerHTML=`<div class="table-wrap"><table><caption style="text-align:left;padding:14px 16px">所选品牌并排比较 · 保持收录顺序</caption><thead><tr><th scope="col">比较项目</th>${bs.map(b=>`<th scope="col">${E(b.name)}</th>`).join('')}</tr></thead><tbody>${rows.map(([title,f])=>`<tr><th scope="row">${title}</th>${bs.map(b=>`<td>${title==='档案'?f(b):E(f(b))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}catch(e){mount.innerHTML=`<div class="notice">${E(e.message)}</div>`;}}
function filterCompareRows(){const q=$('#compare-query')?.value.trim().toLowerCase()||'',coupon=$('#compare-coupon')?.value||'';$$('[data-compare-row]').forEach(el=>el.hidden=!el.dataset.name.toLowerCase().includes(q)||(coupon&&el.dataset.coupon!==coupon));}$('#compare-query')?.addEventListener('input',filterCompareRows);$('#compare-coupon')?.addEventListener('change',filterCompareRows);
async function runSelector(values){const data=await getData();const result=selectCandidates(data.brands,values);$('#selector-count').textContent=`所需计费额度约${result.required.toFixed(1)}GB/月，找到${result.matches.length}家参考匹配。`;$('#selector-results').innerHTML=result.matches.map(({brand:b,plan:p,remaining})=>`<article class="card"><div class="eyebrow">序号${String(data.brands.indexOf(b)+1).padStart(2,'0')} / 参考匹配</div><h3><a href="${href('brands/'+b.id+'/')}">${E(b.name)}</a></h3><p>${E(p.name)}</p><div class="stats-strip"><div><strong>¥${money(p.price)}</strong><small>参考月付</small></div><div><strong>${p.gb}</strong><small>GB / 月</small></div><div><strong>${remaining.toFixed(0)}</strong><small>GB估算余量</small></div></div><p>${E(b.profile.tradeoff)}</p><div class="card-bottom"><a href="${href('brands/'+b.id+'/')}">核对完整资料</a><span>按所填预算匹配</span></div></article>`).join('')||'<div class="empty"><h3>没有符合输入条件的参考档位</h3><p>请复查用量、倍率或预算；未知容量和争议套餐没有被强行加入结果。</p></div>';return{required:result.required,count:result.matches.length,brands:result.matches.map(x=>x.brand.id)};}
function selectorValues(){return{budget:Number($('#budget').value),usage:Number($('#usage').value),multiplier:Number($('#multiplier').value),margin:Number($('#margin').value)};}
$('#selector')?.addEventListener('submit',e=>{e.preventDefault();runSelector(selectorValues()).catch(e=>{$('#selector-count').textContent=e.message;$('#selector-results').innerHTML='';});});if($('#selector'))runSelector(selectorValues()).catch(e=>{$('#selector-count').textContent=e.message;});
async function search(q){const data=await getData();const tokens=q.trim().toLowerCase().split(/\s+/).filter(Boolean);if(!tokens.length){$('#search-count').textContent='输入关键词开始搜索。';$('#search-results').innerHTML='';return;}const matches=data.searchIndex.filter(x=>tokens.every(t=>(x.title+' '+x.description+' '+x.text).toLowerCase().includes(t)));$('#search-count').textContent=`找到${matches.length}条相关内容。`;$('#search-results').innerHTML=matches.map(x=>`<article class="search-result"><small>${E(x.type)}</small><h3><a href="${E(href(x.path))}">${E(x.title)}</a></h3><p>${E(x.description)}</p></article>`).join('')||'<div class="empty"><h3>没有找到相关内容</h3><p>可以尝试品牌名、预算、额度周期或更简短的关键词。</p></div>';}
$('#search-form')?.addEventListener('submit',e=>{e.preventDefault();const q=$('#search-query').value;history.replaceState(null,'','?q='+encodeURIComponent(q));search(q).catch(e=>{$('#search-count').textContent=e.message;});});if($('#search-query')){const q=new URLSearchParams(location.search).get('q');if(q){$('#search-query').value=q;search(q).catch(e=>{$('#search-count').textContent=e.message;});}}
$('#correction-form')?.addEventListener('submit',e=>{e.preventDefault();if(!e.target.reportValidity())return;const note=$('#correction-note').value.trim(),url=$('#correction-url').value.trim();try{if(new URL(url).protocol!=='https:')throw new Error();}catch{$('#correction-status').textContent='请提供有效的HTTPS公开证据链接。';return;}const payload={type:'资料更正草稿',site:'https://jichangnetwork.blog',createdAt:new Date().toISOString(),brand:$('#correction-brand').value||'全站',source:url,note,sent:false};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json;charset=utf-8'}),objectUrl=URL.createObjectURL(blob),a=document.createElement('a');a.href=objectUrl;a.download='机场网络-资料更正草稿.json';a.click();setTimeout(()=>URL.revokeObjectURL(objectUrl),1000);$('#correction-status').textContent='更正草稿已生成并下载；没有发送给站长。';});
addEventListener('storage',e=>{readerStore.invalidate(e.key);if(e.key===keys.compare||e.key===null){selected=read(keys.compare).filter(x=>typeof x==='string'&&/^[a-z0-9-]+$/.test(x)).slice(0,4);refreshCompare();}if(e.key===keys.saved||e.key===null)refreshSave();if(e.key===keys.saved||e.key===keys.history||e.key===null)renderLibrary();});
// Optional browser capability uses the same visible selector and calculation.
if($('#selector')&&document.modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'configure_monthly_reference_match',title:'按预算配置参考匹配',description:'配置页面中的预算、传输量、已确认倍率和余量，更新可见的参考月付候选。不会下单。',inputSchema:{type:'object',properties:{budget:{type:'number',exclusiveMinimum:0},usage:{type:'number',exclusiveMinimum:0},multiplier:{type:'number',minimum:1},margin:{type:'number',minimum:0,maximum:100}},required:['budget','usage','multiplier','margin'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},async execute(input){if(!input||Object.keys(input).some(k=>!['budget','usage','multiplier','margin'].includes(k)))throw new Error('不支持的输入字段。');const data=await getData();selectCandidates(data.brands,input);for(const key of ['budget','usage','multiplier','margin'])$('#'+key).value=String(input[key]);return runSelector(input);}},{signal:lifecycle.signal})).catch(()=>{});}catch{}addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}

const tocLinks=$$('.toc nav a,.dossier-toc nav a');if(tocLinks.length&&'IntersectionObserver' in window){const targets=tocLinks.map(a=>document.getElementById(a.hash.slice(1))).filter(Boolean);const observer=new IntersectionObserver(entries=>{const entry=entries.find(x=>x.isIntersecting);if(entry)tocLinks.forEach(a=>{const active=a.hash==='#'+entry.target.id;a.classList.toggle('is-active',active);if(active)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');});},{rootMargin:'-120px 0px -55% 0px',threshold:0});targets.forEach(el=>observer.observe(el));}
const compactToc=matchMedia('(max-width:960px)');function setTocLayout(){for(const details of $$('.toc details'))details.open=!compactToc.matches;}setTocLayout();compactToc.addEventListener('change',setTocLayout);
